require('dotenv').config();
const express = require('express');
const { Octokit } = require('octokit');
const Groq = require('groq-sdk');

async function classifyIssue(title, body) {
  const prompt = `Classify this GitHub issue. Respond ONLY with valid JSON, no markdown formatting, no code fences, no extra text.

Issue title: ${title}
Issue body: ${body || 'No description provided'}

Respond in this exact JSON format:
{
  "type": "bug" or "feature" or "question",
  "severity": "low" or "medium" or "high",
  "draft_response": "a short one-paragraph response to the issue author"
}`;

  const completion = await groq.chat.completions.create({
    messages: [{ role: 'user', content: prompt }],
    model: 'openai/gpt-oss-120b',
    temperature: 0.3,
    response_format: { type: 'json_object' }
  });

  const text = completion.choices[0].message.content;
  const cleaned = text.replace(/```json|```/g, '').trim();

  try {
    return JSON.parse(cleaned);
  } catch (parseError) {
    console.error('Failed to parse Groq response as JSON:', cleaned);
    // Safe fallback so the pipeline doesn't break
    return {
      type: 'question',
      severity: 'low',
      draft_response: 'Thanks for opening this issue! Our team will review it shortly.'
    };
  }
}

app.post('/webhook/github', async (req, res) => {
  if (req.body.zen) {
    console.log('Ping event received - webhook connected successfully!');
    return res.status(200).send('Pong');
  }

  if (req.body.action !== 'opened') {
    console.log(`Ignored event - action: ${req.body.action}`);
    return res.status(200).send('Ignored - not a new issue');
  }

  const owner = req.body.repository.owner.login;
  const repo = req.body.repository.name;
  const issueNumber = req.body.issue.number;
  const title = req.body.issue.title;
  const body = req.body.issue.body;

  // Idempotency check - respond immediately if already processed
  const issueKey = `${owner}/${repo}#${issueNumber}`;
  if (processedIssues.has(issueKey)) {
    console.log(`Issue ${issueKey} already processed, skipping duplicate webhook`);
    return res.status(200).send('Already processed');
  }
  processedIssues.add(issueKey);

  console.log(`New issue #${issueNumber}: ${title}`);

  try {
    const classification = await classifyIssue(title, body);
    console.log('Groq classification:', classification);

    try {
      await octokit.rest.issues.addLabels({
        owner,
        repo,
        issue_number: issueNumber,
        labels: [classification.type, `severity-${classification.severity}`]
      });
    } catch (labelError) {
      if (labelError.status === 404) {
        console.error(`Label error: one of the labels doesn't exist on repo ${owner}/${repo}. Create labels: ${classification.type}, severity-${classification.severity}`);
      } else if (labelError.status === 401 || labelError.status === 403) {
        console.error('GitHub auth error while labeling - check your GITHUB_TOKEN permissions');
      } else {
        console.error('Unexpected error while labeling:', labelError.message);
      }
    }

    try {
      await octokit.rest.issues.createComment({
        owner,
        repo,
        issue_number: issueNumber,
        body: classification.draft_response
      });
    } catch (commentError) {
      console.error('Error posting comment:', commentError.message);
    }

    console.log(`Finished processing issue ${issueKey}`);
  } catch (error) {
    console.error('Error classifying issue with Groq:', error.message);
    // Remove from processed set so a retry could succeed later
    processedIssues.delete(issueKey);
  }

  res.status(200).send('Received');
});

app.get('/', (req, res) => {
  res.send('AI Issue Triage Bot is running');
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
